class Solution:
    def maxGap(self, skill: str, station: str) -> int:
        n, m = len(skill), len(station)
        def left(t):
            j = 0
            for i in range(t):
                while j < m and station[j] != skill[i]: j += 1
                if j == m: return -1
                j += 1
            return j - 1
        def right(t):
            j = m - 1
            for i in range(n - 1, t - 1, -1):
                while j >= 0 and station[j] != skill[i]: j -= 1
                if j < 0: return -1
                j -= 1
            return j + 1
        ans = 0
        for t in range(1, n):
            a, b = left(t), right(t)
            if a != -1 and b != -1:
                ans = max(ans, b - a)
        return ans

