class Solution {
public:
    int maxGap(string skill, string station) {
        int n = skill.size(), m = station.size();
        auto left = [&](int t) {
            int j = 0;
            for (int i = 0; i < t; i++) {
                while (j < m && station[j] != skill[i]) j++;
                if (j == m) return -1;
                j++;
            }
            return j - 1;
        };
        auto right = [&](int t) {
            int j = m - 1;
            for (int i = n - 1; i >= t; i--) {
                while (j >= 0 && station[j] != skill[i]) j--;
                if (j < 0) return -1;
                j--;
            }
            return j + 1;
        };
        int ans = 0;
        for (int t = 1; t < n; t++) {
            int a = left(t), b = right(t);
            if (a != -1 && b != -1) ans = max(ans, b - a);
        }
        return ans;
    }
};

